import {parseLayout,summary} from './layout-store.js';
export function createLayoutManager(api){const $=s=>document.querySelector(s);let timer,pending=null,pendingLabel='',dirty=false,fileSequence=0;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function save(label='手动保存'){clearTimeout(timer);try{api.store.save(api.model(),label);dirty=false;$('#save-state').textContent='已保存 · '+new Date().toLocaleTimeString();return true;}catch(e){dirty=true;$('#save-state').textContent='保存失败，请导出备份';api.toast(e.message);return false;}}
 function changed(){dirty=true;$('#save-state').textContent='待自动备份';clearTimeout(timer);timer=setTimeout(()=>save('自动备份'),1200);}
 function flush(){return !dirty||save('自动备份');}
 function populate(){try{const history=api.store.history();$('#history-list').innerHTML=history.length?history.map(h=>`<div class="history-row"><b>${esc(h.label)}</b><small>${esc(new Date(h.at).toLocaleString())}</small><p>${esc(summary(h.model))}</p><button data-restore="${esc(h.id)}" ${api.canEdit()?'':'disabled'}>预览恢复</button></div>`).join(''):'<p class="muted">尚无历史版本。编辑后自动备份，也可以点击保存创建版本。</p>';$('#history-list').querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{try{const h=api.store.history().find(x=>x.id===b.dataset.restore);if(!h)throw Error('该版本已不在历史记录中');stage(JSON.stringify(h.model),'恢复版本 · '+new Date(h.at).toLocaleString());}catch(e){api.toast(e.message);}});}catch(e){$('#history-list').textContent=e.message;}}
 function stage(text,label){pending=null;$('#layout-apply').disabled=true;try{const m=parseLayout(text),warnings=api.store.warnings(m);pending=m;pendingLabel=label;$('#import-summary').textContent=`${label}：${summary(m)}。将替换当前完整布局及模拟库存；先备份当前内容。${warnings.length?'存在 '+warnings.length+' 项空间提示，导入后请检查。':''}`;$('#layout-apply').disabled=!api.canEdit();}catch(e){$('#import-summary').textContent='校验失败：'+e.message;}}
 $('#layout-open').onclick=()=>{$('#layout-error').textContent='';$('#layout-mode-note').textContent=api.canEdit()?'导入或恢复前会备份当前布局；确认后立即保存。':'当前为查看模式。切换到编辑模式后才能导入或恢复。';$('#layout-file').disabled=!api.canEdit();$('#layout-apply').disabled=!pending||!api.canEdit();populate();$('#layout-dialog').showModal();};
 $('#layout-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;const sequence=++fileSequence;pending=null;$('#layout-apply').disabled=true;if(file.size>5*1024*1024){$('#import-summary').textContent='校验失败：文件不能超过 5 MB';return;}try{const text=await file.text();if(sequence===fileSequence)stage(text,file.name);}catch(err){if(sequence===fileSequence)$('#import-summary').textContent='读取失败：'+err.message;}};
 $('#layout-apply').onclick=()=>{if(!api.canEdit()||!pending)return;clearTimeout(timer);try{const next=parseLayout(JSON.stringify(pending));api.store.save(next,pendingLabel,api.model());api.replace(next);dirty=false;pending=null;$('#layout-apply').disabled=true;$('#import-summary').textContent='已应用，并保留替换前备份。';$('#save-state').textContent='已保存 · '+new Date().toLocaleTimeString();populate();api.toast('布局已应用，可从历史版本恢复替换前内容');}catch(e){$('#layout-error').textContent='未替换布局：'+e.message;}};
 window.addEventListener('beforeunload',e=>{if(dirty&&!flush()){e.preventDefault();e.returnValue='';}});
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&dirty)flush();});
 return {changed,save,flush};
}
